const fs = require('node:fs');
const crypto = require('node:crypto');
const path = 'products/sites/software-award-brief/index.html';
const source = fs.readFileSync(path);
const html = source.toString('utf8');
const plain = value => value.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const excerpts = [...html.matchAll(/<(h[1-4]|p|li|tr)\b[^>]*>([\s\S]*?)<\/\1>/gi)].map(match => plain(match[2])).filter(text => /award|supplier|contractor|titulaire|fournisseur|attribution/i.test(text)).slice(0, 30);
const links = [...html.matchAll(/<a\b[^>]*\bhref\s*=\s*(["'])(https:\/\/[^"']*)\1[^>]*>([\s\S]*?)<\/a>/gi)].map(match => ({url: match[2].replace(/&amp;/g, '&'), label: plain(match[3])})).filter(link => /find-tender\.service\.gov\.uk|contractsfinder\.service\.gov\.uk|ted\.europa\.eu/i.test(new URL(link.url).hostname));
if (!excerpts.length) throw new Error('No award-related excerpts found');
const evidence = {source: path, sha256: crypto.createHash('sha256').update(source).digest('hex'), scope: 'Lead extraction from a repository brief. Confirm candidate identity in the official award record and verify any current supplier invitation on the prime contractor’s official site.', excerpts, links};
const directory = 'products/services/prime-subcontract-sample';
fs.mkdirSync(directory, {recursive: true});
const output = directory + '/award-brief-leads.json';
fs.writeFileSync(output, JSON.stringify(evidence, null, 2) + '\n');
console.log(JSON.stringify({output, excerpts: excerpts.length, links: links.length, sha256: evidence.sha256}));
